<?php
declare(strict_types=1);
namespace App\Infrastructure\Documents;

/** Bounded, dependency-free reader for the first worksheet of an OOXML workbook. */
final class XlsxReader
{
    public function rows(string $path, int $maxRows = 1001, int $maxColumns = 32): array
    {
        $data=@file_get_contents($path);if($data===false||strlen($data)<22||strlen($data)>2097152)throw new \InvalidArgumentException('El XLSX debe medir entre 1 byte y 2 MB.');
        $files=$this->entries($data);$sheet=$files['xl/worksheets/sheet1.xml']??throw new \InvalidArgumentException('El libro no contiene la primera hoja esperada.');
        $shared=[];if(isset($files['xl/sharedStrings.xml']))foreach($this->matches('/<si\b[^>]*>(.*?)<\/si>/s',$files['xl/sharedStrings.xml']) as$si){$text='';foreach($this->matches('/<t\b[^>]*>(.*?)<\/t>/s',$si)as$part)$text.=$this->decode($part);$shared[]=$text;}
        $rows=[];foreach($this->matches('/<row\b[^>]*>(.*?)<\/row>/s',$sheet)as$rowXml){if(count($rows)>=$maxRows)throw new \InvalidArgumentException('El archivo admite hasta 1,000 filas de datos.');$row=[];foreach($this->matches('/<c\b([^>]*)>(.*?)<\/c>/s',$rowXml,true)as$cell){[$all,$attrs,$body]=$cell;$column=$this->column($attrs);if($column<0||$column>=$maxColumns)throw new \InvalidArgumentException('El archivo contiene columnas fuera de la plantilla.');if(str_contains($body,'<f'))throw new \InvalidArgumentException('La plantilla no admite fórmulas.');$type=preg_match('/\bt="([^"]+)"/',$attrs,$m)?$m[1]:'';$value='';if($type==='inlineStr'){foreach($this->matches('/<t\b[^>]*>(.*?)<\/t>/s',$body)as$part)$value.=$this->decode($part);}elseif(preg_match('/<v\b[^>]*>(.*?)<\/v>/s',$body,$m)){$value=$this->decode($m[1]);if($type==='s'){$index=filter_var($value,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]]);if($index===false||!array_key_exists((int)$index,$shared))throw new \InvalidArgumentException('El XLSX contiene una referencia de texto inválida.');$value=$shared[(int)$index];}}$row[$column]=$value;}if($row!==[]){$width=max(array_keys($row))+1;$values=[];for($i=0;$i<$width;$i++)$values[]=$row[$i]??'';$rows[]=$values;}}
        return$rows;
    }
    private function entries(string$data):array{$eocd=strrpos($data,"PK\x05\x06");if($eocd===false||$eocd+22>strlen($data))throw new \InvalidArgumentException('El archivo no es un XLSX válido.');$count=unpack('v',substr($data,$eocd+10,2))[1];$offset=unpack('V',substr($data,$eocd+16,4))[1];if($count>128)throw new \InvalidArgumentException('El XLSX contiene demasiados archivos internos.');$files=[];$total=0;for($i=0;$i<$count;$i++){if(substr($data,$offset,4)!=="PK\x01\x02")throw new \InvalidArgumentException('El directorio del XLSX está dañado.');$h=unpack('vflags/vmethod/Vcompressed/Vsize/vname/vextra/vcomment/Vlocal',substr($data,$offset+8,4).substr($data,$offset+20,8).substr($data,$offset+28,6).substr($data,$offset+42,4));$name=substr($data,$offset+46,$h['name']);$offset+=46+$h['name']+$h['extra']+$h['comment'];if(($h['flags']&1)!==0||!in_array($h['method'],[0,8],true)||$h['size']>10485760||($total+=$h['size'])>20971520)throw new \InvalidArgumentException('El XLSX usa compresión o tamaños no admitidos.');$local=$h['local'];if(substr($data,$local,4)!=="PK\x03\x04")throw new \InvalidArgumentException('El XLSX contiene una entrada inválida.');$lh=unpack('vname/vextra',substr($data,$local+26,4));$body=substr($data,$local+30+$lh['name']+$lh['extra'],$h['compressed']);$content=$h['method']===8?@gzinflate($body):$body;if($content===false||strlen($content)!==$h['size'])throw new \InvalidArgumentException('No se pudo descomprimir el XLSX.');if(in_array($name,['xl/worksheets/sheet1.xml','xl/sharedStrings.xml'],true))$files[$name]=$content;}return$files;}
    private function column(string$attrs):int{if(!preg_match('/\br="([A-Z]+)\d+"/',$attrs,$m))throw new \InvalidArgumentException('El XLSX contiene una celda sin referencia.');$n=0;foreach(str_split($m[1])as$c)$n=$n*26+ord($c)-64;return$n-1;}
    private function decode(string$value):string{return html_entity_decode(strip_tags($value),ENT_QUOTES|ENT_XML1,'UTF-8');}
    private function matches(string$pattern,string$subject,bool$all=false):array{$ok=preg_match_all($pattern,$subject,$m,$all?PREG_SET_ORDER:PREG_PATTERN_ORDER);if($ok===false)throw new \InvalidArgumentException('El XML del XLSX no es válido.');return$all?$m:($m[1]??[]);}
}
